class Solution {
    public int[][] insert(int[][] intervals, int[] newInterval) {
        java.util.List<int[]> result = new java.util.ArrayList<>();
        int start = newInterval[0];
        int end = newInterval[1];
        int i = 0;
        int n = intervals.length;

        while (i < n && intervals[i][1] < start) {
            result.add(new int[] {intervals[i][0], intervals[i][1]});
            i++;
        }

        while (i < n && intervals[i][0] <= end) {
            start = Math.min(start, intervals[i][0]);
            end = Math.max(end, intervals[i][1]);
            i++;
        }
        result.add(new int[] {start, end});

        while (i < n) {
            result.add(new int[] {intervals[i][0], intervals[i][1]});
            i++;
        }
        return result.toArray(new int[result.size()][]);
    }
}

import java.util.*;

class Solution {
    public int[][] insert(int[][] intervals, int[] newInterval) {
        int n = intervals.length;
        int start = newInterval[0];
        int end = newInterval[1];

        int left = 0;
        int right = n - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (intervals[mid][1] < start) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        int mergeStart = left;

        left = 0;
        right = n - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (intervals[mid][0] <= end) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        int mergeEnd = right;

        List<int[]> result = new ArrayList<>();
        for (int i = 0; i < mergeStart; i++) {
            result.add(new int[] {intervals[i][0], intervals[i][1]});
        }
        for (int i = mergeStart; i <= mergeEnd; i++) {
            start = Math.min(start, intervals[i][0]);
            end = Math.max(end, intervals[i][1]);
        }
        result.add(new int[] {start, end});
        for (int i = mergeEnd + 1; i < n; i++) {
            result.add(new int[] {intervals[i][0], intervals[i][1]});
        }
        return result.toArray(new int[result.size()][]);
    }
}

class Solution {
    public int[][] insert(int[][] intervals, int[] newInterval) {
        int[][] all = new int[intervals.length + 1][2];
        for (int i = 0; i < intervals.length; i++) {
            all[i] = new int[] {intervals[i][0], intervals[i][1]};
        }
        all[intervals.length] = new int[] {newInterval[0], newInterval[1]};
        java.util.Arrays.sort(all, (a, b) -> Integer.compare(a[0], b[0]));

        java.util.List<int[]> merged = new java.util.ArrayList<>();
        for (int[] interval : all) {
            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < interval[0]) {
                merged.add(new int[] {interval[0], interval[1]});
            } else {
                int[] last = merged.get(merged.size() - 1);
                last[1] = Math.max(last[1], interval[1]);
            }
        }
        return merged.toArray(new int[merged.size()][]);
    }
}

import java.util.*;

class Solution {
    public int[][] insert(int[][] intervals, int[] newInterval) {
        TreeMap<Integer, Integer> byStart = new TreeMap<>();
        for (int[] interval : intervals) {
            byStart.put(interval[0], interval[1]);
        }
        byStart.put(newInterval[0], Math.max(byStart.getOrDefault(newInterval[0], newInterval[1]), newInterval[1]));

        List<int[]> result = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : byStart.entrySet()) {
            int mergeStart = entry.getKey();
            int mergeEnd = entry.getValue();
            if (result.isEmpty() || result.get(result.size() - 1)[1] < mergeStart) {
                result.add(new int[] {mergeStart, mergeEnd});
            } else {
                int[] last = result.get(result.size() - 1);
                last[1] = Math.max(last[1], mergeEnd);
            }
        }
        return result.toArray(new int[result.size()][]);
    }
}

import java.util.*;

class Solution {
    public int[][] insert(int[][] intervals, int[] newInterval) {
        TreeMap<Integer, int[]> events = new TreeMap<>();
        addEvent(events, newInterval[0], 1, 0);
        addEvent(events, newInterval[1], 0, 1);
        for (int[] interval : intervals) {
            addEvent(events, interval[0], 1, 0);
            addEvent(events, interval[1], 0, 1);
        }

        List<int[]> result = new ArrayList<>();
        int active = 0;
        int currentStart = -1;
        for (Map.Entry<Integer, int[]> entry : events.entrySet()) {
            int coordinate = entry.getKey();
            int starts = entry.getValue()[0];
            int ends = entry.getValue()[1];
            if (active == 0 && starts > 0) {
                currentStart = coordinate;
            }
            active += starts;
            active -= ends;
            if (active == 0) {
                result.add(new int[] {currentStart, coordinate});
            }
        }
        return result.toArray(new int[result.size()][]);
    }

    private void addEvent(TreeMap<Integer, int[]> events, int coordinate, int starts, int ends) {
        int[] counts = events.computeIfAbsent(coordinate, key -> new int[2]);
        counts[0] += starts;
        counts[1] += ends;
    }
}
